    Q.elections_applied_month = month
    Q.elections_applied_year = year
    Q.election_district_tables_html = districtTableParts.join('')

    report.any = report.executive || report.districts.length > 0 || report.guild
    if (report.any) {
        Q.elections_this_month = 1
        Q.election_report = report.lines.join('\n\n')
    } else {
        Q.elections_this_month = 0
        Q.election_report = ''
    }
    return report
}

