function formatDistrictElectionTableHtml(did, votes, oldSeats, newSeats) {
    const pct = votesToPollPercents(votes || zeroPartyVotes())
    const title = DISTRICT_DISPLAY[did] || did
    let rows = ''
    for (const k of PARTY_KEYS) {
        const color = PARTY_HTML_COLOR[k]
        rows +=
            '<tr>'
            + '<td style="text-align:left;"><span style="color:' + color + ';font-weight:bold;">' + k + '</span></td>'
            + '<td style="text-align:right;">' + pct[k] + '%</td>'
            + '<td style="text-align:right;">' + (newSeats[k] || 0) + '</td>'
            + '<td style="text-align:right;">' + formatSeatChange((newSeats[k] || 0) - (oldSeats[k] || 0)) + '</td>'
            + '</tr>'
    }
    return (
        '<h4 style="margin:0.75em 0 0.25em 0;">' + title + '</h4>'
        + '<table style="width:100%;border-collapse:collapse;font-size:0.85em;margin:0 0 0.5em 0;">'
