#!/usr/bin/env node
/**
 * Dev-only: inject no-cache meta tags into out/html/index.html after a build.
 * out/html/index.html is gitignored — safe for local reload testing (mikasa / make-html).
 *
 * Usage: node scripts/inject-dev-cache-meta.js
 */

const fs = require('fs')
const path = require('path')

const ROOT = path.join(__dirname, '..')
const INDEX = path.join(ROOT, 'out', 'html', 'index.html')
const MARKER = 'mikasa-dev-no-cache'
const SNIPPET = [
  `    <!-- ${MARKER} -->`,
  '    <meta http-equiv="Cache-Control" content="no-cache, no-store, must-revalidate">',
  '    <meta http-equiv="Pragma" content="no-cache">',
  '    <meta http-equiv="Expires" content="0">',
].join('\n')

function stripPrevious(html) {
  const re = new RegExp(
    '\\s*<!-- ' + MARKER + ' -->\\s*'
        + '<meta http-equiv="Cache-Control"[^>]*>\\s*'
        + '<meta http-equiv="Pragma"[^>]*>\\s*'
        + '<meta http-equiv="Expires"[^>]*>\\s*',
    'i'
  )
  return html.replace(re, '\n')
}

function inject() {
  if (!fs.existsSync(INDEX)) {
    console.error('inject-dev-cache-meta: missing', INDEX)
    process.exit(1)
  }

  let html = fs.readFileSync(INDEX, 'utf8')
  html = stripPrevious(html)

  if (html.includes(MARKER)) {
    return
  }

  const headMatch = html.match(/<head[^>]*>/i)
  if (!headMatch) {
    console.error('inject-dev-cache-meta: no <head> in', INDEX)
    process.exit(1)
  }

  const insertAt = headMatch.index + headMatch[0].length
  html = html.slice(0, insertAt) + '\n' + SNIPPET + '\n' + html.slice(insertAt)
  fs.writeFileSync(INDEX, html)
  console.log('inject-dev-cache-meta: added no-cache meta tags to out/html/index.html')
}

inject()

#!/usr/bin/env node
/**
 * Dev-only patches to out/html/index.html (gitignored).
 *
 * Meta no-cache tags rarely help for file:// or for subresources (game.js).
 * This script also appends ?v=<build-stamp> to CSS/JS URLs so Firefox reloads
 * them after each `npm run make-html` / `mikasa`.
 *
 * Usage: node scripts/inject-dev-cache-meta.js
 */

const fs = require('fs')
const path = require('path')

const ROOT = path.join(__dirname, '..')
const INDEX = path.join(ROOT, 'out', 'html', 'index.html')
const STAMP_FILE = path.join(ROOT, 'out', 'html', 'build-stamp.txt')
const MARKER = 'mikasa-dev-no-cache'
const DEV_ASSETS = ['game.css', 'jquery-1.11.1.min.js', 'core.js', 'game.js']

const META_SNIPPET = [
  `    <!-- ${MARKER} -->`,
  '    <meta http-equiv="Cache-Control" content="no-cache, no-store, must-revalidate">',
  '    <meta http-equiv="Pragma" content="no-cache">',
  '    <meta http-equiv="Expires" content="0">',
].join('\n')

function escapeReg(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

function readBuildVersion() {
  if (fs.existsSync(STAMP_FILE)) {
    return fs.readFileSync(STAMP_FILE, 'utf8').trim().replace(/[^\w.-]+/g, '_')
  }
  return String(Date.now())
}

function stripMeta(html) {
  const re = new RegExp(
    '\\s*<!-- ' + MARKER + ' -->\\s*'
        + '<meta http-equiv="Cache-Control"[^>]*>\\s*'
        + '<meta http-equiv="Pragma"[^>]*>\\s*'
        + '<meta http-equiv="Expires"[^>]*>\\s*',
    'i'
  )
  return html.replace(re, '\n')
}

function stripAssetBust(html) {
  let out = html
  for (const asset of DEV_ASSETS) {
    out = out.replace(
      new RegExp(`((?:src|href)=["'])${escapeReg(asset)}\\?v=[^"']*(["'])`, 'gi'),
      `$1${asset}$2`
    )
  }
  return out
}

function injectMeta(html) {
  html = stripMeta(html)
  if (html.includes(MARKER)) {
    return html
  }
  const headMatch = html.match(/<head[^>]*>/i)
  if (!headMatch) {
    console.error('inject-dev-cache-meta: no <head> in', INDEX)
    process.exit(1)
  }
  const insertAt = headMatch.index + headMatch[0].length
  return html.slice(0, insertAt) + '\n' + META_SNIPPET + '\n' + html.slice(insertAt)
}

function bustAssetUrls(html, version) {
  html = stripAssetBust(html)
  const q = encodeURIComponent(version)
  for (const asset of DEV_ASSETS) {
    html = html.replace(
      new RegExp(`((?:src|href)=["'])${escapeReg(asset)}(["'])`, 'gi'),
      `$1${asset}?v=${q}$2`
    )
  }
  return html
}

function inject() {
  if (!fs.existsSync(INDEX)) {
    console.error('inject-dev-cache-meta: missing', INDEX)
    process.exit(1)
  }

  const version = readBuildVersion()
  const before = fs.readFileSync(INDEX, 'utf8')
  let html = injectMeta(before)
  html = bustAssetUrls(html, version)

  if (html !== before) {
    fs.writeFileSync(INDEX, html)
    console.log(
      'inject-dev-cache-meta: patched out/html/index.html'
      + ` (assets ?v=${version})`
    )
  }
}

inject()

module.exports = { readBuildVersion, bustAssetUrls, DEV_ASSETS }

#!/usr/bin/env node
/**
 * Local static server for out/html with no-store on every response.
 * Prefer this over file:// when Firefox keeps stale game.js.
 *
 * Usage:
 *   node scripts/serve-dev.js
 *   MIKASA_DEV_PORT=8765 node scripts/serve-dev.js
 *
 * Open http://127.0.0.1:8765/ (WSL2 usually forwards localhost to Windows Firefox).
 */

const http = require('http')
const fs = require('fs')
const path = require('path')

const ROOT = path.join(__dirname, '..', 'out', 'html')
const PORT = parseInt(process.env.MIKASA_DEV_PORT || '8765', 10)

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'application/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.txt': 'text/plain; charset=utf-8',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
}

function send(res, status, body, type) {
  res.writeHead(status, {
    'Content-Type': type || 'text/plain; charset=utf-8',
    'Cache-Control': 'no-store, no-cache, must-revalidate',
    Pragma: 'no-cache',
    Expires: '0',
  })
  res.end(body)
}

const server = http.createServer((req, res) => {
  let rel = decodeURIComponent((req.url || '/').split('?')[0])
  if (rel === '/') rel = '/index.html'
  const file = path.normalize(path.join(ROOT, rel.replace(/^\//, '')))
  if (!file.startsWith(ROOT)) {
    send(res, 403, 'Forbidden')
    return
  }
  fs.readFile(file, (err, data) => {
    if (err) {
      send(res, err.code === 'ENOENT' ? 404 : 500, err.message)
      return
    }
    send(res, 200, data, MIME[path.extname(file)] || 'application/octet-stream')
  })
})

server.listen(PORT, '127.0.0.1', () => {
  console.log(`mikasa dev server: http://127.0.0.1:${PORT}/  (root ${ROOT})`)
})

