function syncStratumProsperityAverages(state) {
    for (const sid of STRATUM_IDS) {
        let popSum = 0
        let weighted = 0
        for (const block of state.blocks) {
            if (block.demographic.id !== sid) { continue }
            const pop = block.population
            if (pop <= 0) { continue }
            popSum += pop
            weighted += pop * (block.prosperity ?? 1)
        }
        Q['prosperity_' + sid] = popSum > 0 ? weighted / popSum : 1
    }
}

